-- 1THESSALONIANS - POR Combined
-- Generated: 2026-01-22T06:35:33.448Z

-- c005-v001: Acerca porém dos tempos e das épocas irmãos não necessidade tendes a–vós escrever–se
-- c005-v002: vós–mesmos pois exatamente sabeis que o–dia do–Senhor como ladrão de noite assim vem
-- c005-v003: quando disserem Paz e segurança então repentina sobre–eles sobrevém destruição como a dor–de–parto à em ventre que–tem e de–modo–nenhum não escaparão
-- c005-v004: vós porém irmãos não estais em trevas para–que o dia a–vós como ladrão surpreenda
-- c005-v005: todos pois vós filhos da–luz sois e filhos do–dia não somos da–noite nem das–trevas
-- c005-v006: portanto pois não durmamos como os demais mas vigiemos e sejamos–sóbrios
-- c005-v007: os pois que–dormem de–noite dormem e os que–se–embriagam de–noite se–embriagam
-- c005-v008: nós porém do–dia sendo sejamos–sóbrios tendo–vestido couraça da–fé e do–amor e capacete esperança da–salvação
-- c005-v009: porque não designou a–nós o Deus para ira mas para obtenção de–salvação por–meio–do o Senhor nosso Jesus Cristo
-- c005-v010: do que–morreu por nós para–que quer vigiemos quer durmamos juntamente com ele vivamos
-- c005-v011: Por–isso consolai uns–aos–outros e edificai um ao outro assim–como também fazeis
-- c005-v012: Rogamos porém a–vós irmãos reconhecer os que–trabalham entre vós e que–presidem sobre–vós no Senhor e que–vos–admoestam a–vós
-- c005-v013: e estimá–los a–eles abundantemente em amor por–causa–de a obra deles tende–paz entre vós–mesmos
-- c005-v014: Exortamos porém a–vós irmãos admoestai os desordenados consolai os desanimados amparai os fracos sede–pacientes para–com todos
-- c005-v015: vede que–não alguém mal por mal a–alguém retribua mas sempre o bem buscai e uns–para os–outros e para todos
-- c005-v016: Sempre alegrai–vos
-- c005-v017: incessantemente orai
-- c005-v018: em tudo dai–graças isto pois vontade de–Deus em Cristo Jesus para vós
-- c005-v019: o Espírito não apagueis
-- c005-v020: profecias não desprezeis
-- c005-v021: todas–as–coisas porém examinai o bom retende
-- c005-v022: de toda aparência do–mal abstende–vos
-- c005-v023: Ele–mesmo porém o Deus da paz vos–santifique a–vós completamente e inteiramente vosso o espírito e a alma e o corpo irrepreensivelmente na a vinda do Senhor nosso Jesus Cristo seja–guardado
-- c005-v024: fiel o que–chama a–vós o–qual também fará
-- c005-v025: Irmãos orai também por nós
-- c005-v026: Saudai os irmãos todos com ósculo santo
-- c005-v027: Conjuro–vos a–vós pelo Senhor ser–lida a epístola a–todos os irmãos
-- c005-v028: A graça do Senhor nosso Jesus Cristo convosco vós Amém

